export const workflowMessages: Readonly<Record<SupportedLocale, Catalog & RuntimeCatalog & SelectionErrorCatalog & CoverageCatalog>> = Object.fromEntries(
  (Object.keys({ en, ...translations }) as SupportedLocale[]).map((locale) => [
    locale,
    {
      ...(locale === 'en' ? en : translations[locale]),
      ...(locale === 'en' ? runtimeEn : runtimeTranslations[locale]),
      ...(locale === 'en' ? selectionErrorEn : selectionErrorTranslations[locale]),
      ...(locale === 'en' ? coverageEn : coverageTranslations[locale]),
    },
  ]),
) as Record<SupportedLocale, Catalog & RuntimeCatalog & SelectionErrorCatalog & CoverageCatalog>;
